INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(1406001, '', 'Backhand nearby enemies, dazing them and knocking them back.', 'Backhand nearby enemies, dazing them and knocking them back.', 69933),
(1406002, '', 'Headbutt your foes, hurling them back and bruising them.', 'Headbutt your foes, hurling them back and bruising them.', 69933),
(1406003, '', 'Slam the ground with all your weight, damaging enemies around you and throwing them back.', 'Slam the ground with all your weight, damaging enemies around you and throwing them back.', 69933),
(1406004, '', 'Strike with a fist of raw arcane energy.', 'Strike with a fist of raw arcane energy.', 69933),
(1406005, '', 'A wave of astral energy rolls out from you, damaging all nearby enemies.', 'A wave of astral energy rolls out from you, damaging all nearby enemies.', 69933),
(1406006, '', 'A burst of ammolite shards strikes the target instantly.', 'A burst of ammolite shards strikes the target instantly.', 69933),
(1406007, '', 'Splash the target with burning sludge that eats away at it over time.', 'Splash the target with burning sludge that eats away at it over time.', 69933),
(1406008, '', 'Seize the target and drag it to your side.', 'Seize the target and drag it to your side.', 69933),
(1406009, '', 'Addle the target''s mind so it stumbles around in confusion.', 'Addle the target''s mind so it stumbles around in confusion.', 69933),
(1406010, '', 'Burst out in acid, scorching all nearby enemies.', 'Burst out in acid, scorching all nearby enemies.', 69933),
(1406011, '', 'Let loose a cry of anguish that sends nearby enemies fleeing in terror.', 'Let loose a cry of anguish that sends nearby enemies fleeing in terror.', 69933),
(1406012, '', 'Reach out with shadow and strike a distant enemy.', 'Reach out with shadow and strike a distant enemy.', 69933),
(1406013, '', 'Sink fangs into the target, poisoning it.', 'Sink fangs into the target, poisoning it.', 69933),
(1406014, '', 'A stinger that stiffens the target in place for a short while.', 'A stinger that stiffens the target in place for a short while.', 69933),
(1406015, '', 'Hurl a spear of corrosive bile at the target.', 'Hurl a spear of corrosive bile at the target.', 69933),
(1406016, '', 'Infect the target with a void toxin that gnaws at it over time.', 'Infect the target with a void toxin that gnaws at it over time.', 69933),
(1406017, '', 'Snuff out a piece of the target''s soul. Deals more damage to weakened enemies.', 'Snuff out a piece of the target''s soul. Deals more damage to weakened enemies.', 69933),
(1406018, '', 'Strike with the speed of a serpent.', 'Strike with the speed of a serpent.', 69933),
(1406019, '', 'Twisting toxins burn the target and keep burning.', 'Twisting toxins burn the target and keep burning.', 69933),
(1406020, '', 'Vitriol sprays out and holds nearby enemies in place.', 'Vitriol sprays out and holds nearby enemies in place.', 69933),
(1406021, '', 'Toxic droplets rain on the area, poisoning everyone inside.', 'Toxic droplets rain on the area, poisoning everyone inside.', 69933),
(1406022, '', 'A shifting cloud of miasma burns everything beneath it.', 'A shifting cloud of miasma burns everything beneath it.', 69933),
(1406023, '', 'Night falls forever in the target area, harming foes within.', 'Night falls forever in the target area, harming foes within.', 69933),
(1406024, '', 'A ghastly mending closes your wounds over time.', 'A ghastly mending closes your wounds over time.', 69933),
(1406025, '', 'A well of coiling souls restores nearby allies.', 'A well of coiling souls restores nearby allies.', 69933),
(1406026, '', 'Plant a venomous ward that slows enemies who come too close.', 'Plant a venomous ward that slows enemies who come too close.', 69933),
(1406027, '', 'Call an ancient guardian spirit to fight at your side.', 'Call an ancient guardian spirit to fight at your side.', 69933),
(1406028, '', 'Step through the spirit world to a point ahead of you.', 'Step through the spirit world to a point ahead of you.', 69933),
(1406029, '', 'Fall into a bestial berserk, greatly increasing your haste.', 'Fall into a bestial berserk, greatly increasing your haste.', 69933),
(1406030, '', 'The Medjai''s protection wraps you in a barrier that absorbs damage.', 'The Medjai''s protection wraps you in a barrier that absorbs damage.', 69933),
(1406031, '', 'A bulwark of arcane force shields you from the front.', 'A bulwark of arcane force shields you from the front.', 69933),
(1406032, '', 'Ward an ally with an arcane shield that absorbs damage.', 'Ward an ally with an arcane shield that absorbs damage.', 69933),
(1406033, '', 'Throw a vial of Vashnik''s poison mixture at the target.', 'Throw a vial of Vashnik''s poison mixture at the target.', 69933),
(1406040, '', 'A blessing of flame empowers your fire, increasing Fire damage by 12% for 20 sec.', 'A blessing of flame empowers your fire, increasing Fire damage by 12% for 20 sec.', 69933),
(1406041, '', 'Don the ancient Amani mask. Critical strike chance and haste are increased for 30 sec.', 'Don the ancient Amani mask. Critical strike chance and haste are increased for 30 sec.', 69933),
(1406042, '', 'An agitated crystal hums at your side: Intellect +5% and critical strike +3% for 30 sec.', 'An agitated crystal hums at your side: Intellect +5% and critical strike +3% for 30 sec.', 69933),
(1406043, '', 'Akil''zon''s rite fills you with storm. Nature damage +10% and haste +5% for 20 sec.', 'Akil''zon''s rite fills you with storm. Nature damage +10% and haste +5% for 20 sec.', 69933),
(1406044, '', 'Gorge on a mighty Midnight salmon. Stamina is increased by 5% for 1 hour.', 'Gorge on a mighty Midnight salmon. Stamina is increased by 5% for 1 hour.', 69933),
(1406045, '', 'Charge builds up inside you, increasing haste by 8% for 15 sec.', 'Charge builds up inside you, increasing haste by 8% for 15 sec.', 69933),
(1406046, '', 'An echo of Ula''tek roars through you: critical strike +10% and haste +10% for 15 sec.', 'An echo of Ula''tek roars through you: critical strike +10% and haste +10% for 15 sec.', 69933),
(1406047, '', 'Ula''tek''s dominance takes hold. Attack power +15% and all damage +10% for 20 sec.', 'Ula''tek''s dominance takes hold. Attack power +15% and all damage +10% for 20 sec.', 69933),
(1406048, '', 'Venom coagulates into a hard crust. Damage taken is reduced by 15% for 12 sec.', 'Venom coagulates into a hard crust. Damage taken is reduced by 15% for 12 sec.', 69933);
